module.exports = async function(data) {
  // Generate a readable invite token like WLR-YMTWBI
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let inviteCode = "WLR-";

  for (let i = 0; i < 6; i++) {
    inviteCode += chars[Math.floor(Math.random() * chars.length)];
  }

  // Current send time
  const now = new Date();

  // Expiration date: 7 days from now
  const expiresAt = new Date(now);
  expiresAt.setDate(expiresAt.getDate() + 7);

  // Frontend claim URL
  const frontendUrl = "[REDACTED_INVITE_FRONTEND_URL]";
  const claimUrl = `${frontendUrl}/invites/claim?token=${encodeURIComponent(inviteCode)}`;

  return {
    token: inviteCode,
    invite_code: inviteCode,
    sent_at: now.toISOString(),
    expires_at: expiresAt.toISOString(),
    status: "pending",
    claim_url: claimUrl
  };
};

module.exports = async function(data) {
  const body =
    data?.$trigger?.body ||
    data?.$trigger?.payload ||
    data?.payload ||
    data?.body ||
    {};

  const token =
    body.token ||
    body.invite ||
    body.code ||
    null;

  if (!token || typeof token !== "string") {
    throw new Error("Invite token is missing.");
  }

  const normalizedToken = token.trim().toUpperCase();
  const now = new Date();

  return {
    token: normalizedToken,
    now: now.toISOString()
  };
};

module.exports = async function(data) {
  const result = data.find_invite;

  let invite = null;

  if (Array.isArray(result)) {
    invite = result[0] || null;
  } else if (Array.isArray(result?.data)) {
    invite = result.data[0] || null;
  } else {
    invite = result || null;
  }

  if (!invite) {
    throw new Error("Invite not found, already used, or invalid.");
  }

  if (!invite.id) {
    throw new Error("Invite id is missing.");
  }

  if (!invite.token) {
    throw new Error("Invite token is missing in database.");
  }

  if (invite.status !== "pending") {
    throw new Error(`Invite is not pending. Current status: ${invite.status}`);
  }

  if (invite.expires_at) {
    const expiresAt = new Date(invite.expires_at);
    const now = new Date();

    if (Number.isNaN(expiresAt.getTime())) {
      throw new Error("Invite expiry date is invalid.");
    }

    if (expiresAt < now) {
      throw new Error("Invite expired.");
    }
  }

  if (!invite.email) {
    throw new Error("Invite email is missing.");
  }

  if (!invite.business_profile) {
    throw new Error("Invite business profile is missing.");
  }

  if (!invite.member_role) {
    throw new Error("Invite member role is missing.");
  }

  let normalizedRole = String(invite.member_role || "")
    .toLowerCase()
    .trim();

  const roleAliases = {
    manger: "manager"
  };

  normalizedRole = roleAliases[normalizedRole] || normalizedRole;

  const allowedRoles = ["owner", "hr", "manager", "employee"];

  if (!allowedRoles.includes(normalizedRole)) {
    throw new Error(`Invite member role is invalid: ${invite.member_role}`);
  }

  return {
    invite_id: invite.id,
    token: invite.token,
    invite_email: String(invite.email).toLowerCase().trim(),
    business_profile: invite.business_profile,
    department: invite.department || null,
    member_role: normalizedRole
  };
};

module.exports = async function(data) {
  const userId =
    data?.$accountability?.user ||
    data?.$trigger?.accountability?.user ||
    data?.accountability?.user ||
    data?.$trigger?.headers?.["x-user-id"] ||
    null;

  if (!userId) {
    throw new Error("You must be logged in to accept this invite.");
  }

  return {
    user_id: userId
  };
};

module.exports = async function(data) {
  const result = data.read_current_user;

  let user = null;

  if (Array.isArray(result)) {
    user = result[0] || null;
  } else if (Array.isArray(result?.data)) {
    user = result.data[0] || null;
  } else {
    user = result || null;
  }

  const invite = data.validate_invite;

  if (!user || !user.id) {
    throw new Error("Current user was not found.");
  }

  if (!user.email) {
    throw new Error("Current user email is missing.");
  }

  const userEmail = String(user.email).toLowerCase().trim();
  const inviteEmail = String(invite.invite_email).toLowerCase().trim();

  if (userEmail !== inviteEmail) {
    throw new Error("This invite was sent to another email.");
  }

  return {
    user_id: user.id,
    user_email: userEmail,
    invite_id: invite.invite_id,
    business_profile: invite.business_profile,
    department: invite.department,
    member_role: invite.member_role
  };
};

module.exports = async function(data) {
  const result = data.check_existing_membership;

  let membership = null;

  if (Array.isArray(result)) {
    membership = result[0] || null;
  } else if (Array.isArray(result?.data)) {
    membership = result.data[0] || null;
  } else {
    membership = result || null;
  }

  const claim = data.validate_user_email;

  if (membership && membership.id) {
    return {
      already_member: true,
      membership_id: membership.id,
      user_id: claim.user_id,
      business_profile: claim.business_profile,
      department: claim.department,
      member_role: claim.member_role
    };
  }

  return {
    already_member: false,
    membership_id: null,
    user_id: claim.user_id,
    business_profile: claim.business_profile,
    department: claim.department,
    member_role: claim.member_role
  };
};

module.exports = async function(data) {
  const rawRole = String(data.validate_user_email?.member_role || "")
    .toLowerCase()
    .trim();

  const roleAliases = {
    manger: "manager"
  };

  const normalizedRole = roleAliases[rawRole] || rawRole;

  const roleIds = {
    owner: "b293f748-436b-4957-bab0-c3111fb6a52e",
    hr: "068ea7ce-c549-480d-8ebd-fce901aae4ef",
    manager: "417b3bf9-1ab9-4f9a-bb38-c464ae35ecaa",
    employee: "70f73477-0435-4bcf-91f0-1915c27eea1a"
  };

  const directusRoleId = roleIds[normalizedRole];

  if (!directusRoleId) {
    throw new Error(`No Directus role configured for member_role: ${rawRole}`);
  }

  return {
    original_member_role: rawRole,
    member_role: normalizedRole,
    directus_role_id: directusRoleId
  };
};

